// Print response body in summary format
const jsonData = pm.response.json();
console.log('=== RESULTS SUMMARY ===');

if (jsonData.length === 0) {
    console.log('No results found');
} else {
    jsonData.forEach(result => {
        console.log('---');
        console.log('result_id: ' + result.resultId);
        console.log('session_id: ' + result.sessionId);
        console.log('total_score: ' + result.totalScore);
        console.log('created_at: ' + result.createdAt);
        console.log('national_id: ' + result.nationalId);
        console.log('full_name: ' + result.fullName);
    });
}
